BEGIN;
INSERT INTO property(property_name,address) VALUES('G05 A4 probe','Local test') RETURNING property_id AS pid \gset
INSERT INTO room(property_id,room_number,monthly_rate) VALUES(:pid,'probe',100) RETURNING room_id AS rid \gset
INSERT INTO tenant(full_name,contact_number,email) VALUES('G05 A4 probe','000','g05-a4@example.invalid') RETURNING tenant_id AS tid \gset
INSERT INTO lease(tenant_id,room_id,start_date,end_date,monthly_rent) VALUES(:tid,:rid,'2099-01-01','2099-12-31',100) RETURNING lease_id AS lid \gset
SELECT status AS room_after_insert FROM room WHERE room_id=:rid;
INSERT INTO payment(lease_id,amount,payment_method) VALUES(:lid,100,'CASH');
INSERT INTO utility_bill(lease_id,billing_period,utility_type,amount) VALUES(:lid,'2099-01-01','WATER',20);
UPDATE property SET property_name='G05 A4 updated' WHERE property_id=:pid;
UPDATE room SET monthly_rate=120 WHERE room_id=:rid;
UPDATE tenant SET full_name='G05 A4 updated' WHERE tenant_id=:tid;
UPDATE lease SET monthly_rent=120 WHERE lease_id=:lid;
UPDATE payment SET amount=110 WHERE lease_id=:lid;
UPDATE utility_bill SET amount=25 WHERE lease_id=:lid;
SELECT total_paid,utilities_billed FROM v_lease_summary WHERE lease_id=:lid;
UPDATE lease SET status='TERMINATED' WHERE lease_id=:lid;
SELECT status AS room_after_termination FROM room WHERE room_id=:rid;
DELETE FROM payment WHERE lease_id=:lid;
DELETE FROM utility_bill WHERE lease_id=:lid;
DELETE FROM lease WHERE lease_id=:lid;
DELETE FROM tenant WHERE tenant_id=:tid;
DELETE FROM room WHERE room_id=:rid;
DELETE FROM property WHERE property_id=:pid;
ROLLBACK;

SELECT version(),current_database();
SELECT rolname,rolcanlogin,rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolbypassrls,rolinherit FROM pg_roles WHERE rolname LIKE 'boardtrack_%' ORDER BY 1;
SELECT a.rolname AS member,b.rolname AS parent,m.admin_option,m.inherit_option,m.set_option FROM pg_auth_members m JOIN pg_roles a ON a.oid=m.member JOIN pg_roles b ON b.oid=m.roleid WHERE a.rolname LIKE 'boardtrack_%';
SELECT datname,pg_get_userbyid(datdba),datacl FROM pg_database ORDER BY datname;
SELECT nspname,nspacl FROM pg_namespace WHERE nspname='public';
SELECT c.relname,c.relkind,pg_get_userbyid(c.relowner) AS owner,c.relacl FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN('r','S','v') ORDER BY c.relname;
SELECT proname,pg_get_userbyid(proowner),prosecdef,proacl FROM pg_proc p WHERE pronamespace='public'::regnamespace AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e') ORDER BY proname;
SELECT t.tgrelid::regclass,t.tgname,t.tgenabled FROM pg_trigger t WHERE NOT t.tgisinternal ORDER BY 1,2;
SELECT extname,extversion FROM pg_extension ORDER BY 1;
SELECT defaclrole::regrole,defaclobjtype,defaclacl FROM pg_default_acl;
SELECT conrelid::regclass,conname,pg_get_constraintdef(oid) FROM pg_constraint WHERE connamespace='public'::regnamespace ORDER BY 1,2;
SELECT 'property',count(*) FROM property UNION ALL SELECT 'room',count(*) FROM room UNION ALL SELECT 'tenant',count(*) FROM tenant UNION ALL SELECT 'lease',count(*) FROM lease UNION ALL SELECT 'payment',count(*) FROM payment UNION ALL SELECT 'utility_bill',count(*) FROM utility_bill UNION ALL SELECT 'app_user',count(*) FROM app_user UNION ALL SELECT 'schema_migrations',count(*) FROM schema_migrations;
SELECT to_regclass('g05_future_probe') IS NULL AS probe_table_removed,to_regprocedure('g05_future_function()') IS NULL AS probe_function_removed;
